  assert.equal(ops[0].value[1].contextWindow, 1)
})

test('parseCatalogFile and stale detection', () => {
  const file = parseCatalogFile({ updatedAt: '2020-01-01T00:00:00.000Z', autoFill: false, models: [{ id: 'a' }] })
